// Google Sheets cells cannot hold arrays or objects: flatten the SSL Labs summary.
return $input.all().map(({ json }) => ({
  json: {
    host: json.host,
    status: json.status,
    grade: json.grade ?? '',
    bestGrade: json.bestGrade ?? '',
    hasWarnings: json.hasWarnings ?? false,
    endpoints: (json.endpoints || []).map((e) => `${e.ipAddress} (${e.grade ?? e.statusMessage ?? 'n/a'})`).join(', '),
    certificateIssuer: json.certificate?.issuer ?? '',
    certificateExpires: json.certificate?.notAfter ?? '',
    daysUntilExpiry: json.certificate?.daysUntilExpiry ?? '',
    testTime: json.testTime ?? '',
    reportUrl: json.reportUrl,
    error: json.error ?? '',
  },
}));

// Build one plain-text summary of all assessed hosts for the email.
const hosts = $input.all().map((item) => item.json);
const lines = hosts.map((h) => {
  if (h.error) return `${h.host ?? 'unknown host'}: assessment failed (${h.error})`;
  const days = h.certificate?.daysUntilExpiry;
  const cert = days === null || days === undefined ? '' : `; certificate expires in ${days} day(s)`;
  const warn = h.hasWarnings ? ' [warnings]' : '';
  return `${h.host}: grade ${h.grade ?? 'n/a'}${warn}${cert}\n  ${h.reportUrl}`;
});
const weak = hosts.filter((h) => h.grade && !['A+', 'A', 'A-'].includes(h.grade));
return [{
  json: {
    subject: `Weekly SSL report: ${hosts.length} host(s), ${weak.length} below A-`,
    body: ['SSL Labs weekly grade report', '', ...lines].join('\n'),
  },
}];
